def search_pascal_multiples_fast(row_limit):
    try:
        res_ptr = func(
            row_limit,
            ctypes.cast(libc.malloc, ctypes.c_void_p),
            ctypes.cast(libc.calloc, ctypes.c_void_p),
            ctypes.cast(libc.free, ctypes.c_void_p),
        )
        # Parse C output
        results = []
        i = 0
        while not (res_ptr[i].lo == 0 and res_ptr[i].hi == 0):
            results.append((res_ptr[i].hi << 64) | res_ptr[i].lo)
            i += 1

        return results
    except:
        # Fallback code to get my assignment accepted if it is not run on macos with arm cpu
        counter = Counter()

        p_row = [1] * row_limit
        p_row[0] = 3
        for i in range(4, row_limit, 2):
            p_row[i // 2 - 1] += p_row[i // 2 - 2]
            for j in range(i // 2 - 2, 0, -1):
                p_row[j] += p_row[j - 1]
                counter[p_row[j]] += 2
            p_row[0] *= 2
            counter[p_row[0]] += 1

            i += 1
            for j in range(0, i // 2 - 1):
                p_row[j] = p_row[j] + p_row[j + 1]
                counter[p_row[j]] += 2
            p_row[i // 2 - 1] += p_row[i // 2]

        return sorted([k for k, v in counter.items() if v > 3])

